```groovy
import com.onemonkeylabs.plugin.ScriptPlugin

class BlockIssueFromMovingIfChecklistIsComplete implements ScriptPlugin {
    @Field("Checklist Name") String checklistName

    @Step(name="Checklist Completed", description="Check whether the specified checklist is complete or not.")
    boolean checklistCompleted(Context context) {
        def issue = context.issue
        def checklists = issue.getCheckListItems()
        def checklist = checklists.find { it.checklist.name == checklistName }
        return checklist?.all { it.done } ? : false
    }

    @Step(name="Prevent Issue Move", description="Prevent issue move if checklist is complete.")
    void preventMove(Context context) {
        def transition = context.transition
        def issue = context.issue
        if (transition.name == 'To Do' || transition.name == 'In Progress') { // only prevent moves from To Do or In Progress
            if (checklistCompleted()) { // check if checklist is complete
                throw new Exception("The checklist is not completed yet. Please complete the checklist before moving the issue.")
            }
        }
    }
}
```

3. Save the script and activate it in the Script Console.
4. Go to the JIRA board settings and add the new script to the post-function scripts for the desired transition(s).
