  const [firstAdjective, ...rest] = words.slice(0, adjectiveIndex + 2);
  const [secondAdjective, ...otherWords] = rest.slice(1);
  const newSentence = [secondAdjective, ...firstAdjective, ...otherWords];

  // Join the new array into a string and trim any leading/trailing whitespace
  return newSentence.join(' ') .trim();
}

