```javascript
const axios = require('axios');

function sendMessageToSlackChannel(text, channel) {
  const options = {
    method: 'POST',
    url: 'https://slack.com/api/chat.postMessage',
    headers: {
      'Content-type': 'application/json; charset=utf-8',
      Authorization: `Bearer YOUR_SLACK_API_TOKEN`
