```java
import com.sox.Sox;
import java.io.*;

public class AudioBlender {
    public static void main(String[] args) throws Exception {
        String input1 = "birds.wav";
        String input2 = "leaves.wav";
        String input3 = "cicadas.wav";
        String input4 = "children.wav";
        String outputFile = "summerday.wav";

