        sox.addBef("normalize", ""); // normalize second input
        sox.addBef("amplify", "1.5"); // amplify third input by 150%
        sox.addBef("pan", "stereo"); // pan fourth input to right channel
        sox.addBef("mix", "3"); // mix all inputs with weights 3 (default)
        sox.addOut("output");
        sox.addOut("file", outputFile);

        sox.build();
        sox.run(args);
        sox.destroy();

        System.out.println("Audio blended and saved to " + outputFile);
