      // Default behavior: sort strings lexicographically
      result = 0;

      // If sort order is descending, reverse the comparison
      if (sortOrder === 'desc') {
        result = -result;
      }
    } else if (valB > valA) {
      // If valB comes before valA, swap their positions
      [keyA, keyB] = [keyB, keyA];
      [valA, valB] = [valB, valA];

