// Recursive function to calculate Fibonacci sequence
unsigned long long fibonacci(int n, int a, int b) {
    if (n == 0) return 0; // Base case
    return fibonacci(n - 1, b, a + b); // Recursive case
}

int main() {
    std::string input;
    int num1, num2, numElements;

    std::cout << "Enter the first Fibonacci number: ";
    std::getline(std::cin, input);

