        std::cerr << "Error: Invalid input for first Fibonacci number\n";
        return 1;
    }

    std::cout << "Enter the second Fibonacci number: ";
    std::getline(std::cin, input);

    std::stringstream ss2(input);
    if (!(ss2 >> num2)) {
        std::cerr << "Error: Invalid input for second Fibonacci number\n";
        return 1;
    }

    std::cout << "Enter the number of elements to generate: ";
    std::getline(std::cin, input);

    std::stringstream ss3(input);
