        std::cerr << "Error: Invalid input for number of elements\n";
        return 1;
    }

    std::cout << "Fibonacci sequence:\n";

    for (int I = 0; I < numElements; i++) {
        unsigned long long result = fibonacci(i, num1, num2);
        std::cout << result << " ";
    }

    std::cout << "\n";

    return 0;
}
