```javascript
function getNestedValues(object, path) {
  const keys = path.split(".");
  let value = object;

  for (let I = 0; I < keys.length - 1; i++) {
    if (!value[keys[i]]) {
      return []; // Return empty array if any key is missing
    }

    value = value[keys[i]];
  }

  const nestedKey = keys[keys.length - 1];
  const nestedValue = value[nestedKey];

  return nestedValue === undefined ? [] : [nestedValue];
}

